function tableFor(modelKey: string): string {
  const override = (() => {
    try { return JSON.parse(process.env.SUPABASE_TABLE_MAP || '{}'); } catch { return {}; }
  })() as Record<string, string>;
  return override[modelKey] || MODEL_TABLES[modelKey] || modelKey;
}

// ── Client 構造（優先 service role；anon 為後備）──
function resolveEnv(opts?: { url?: string; key?: string }) {
  const url = opts?.url || process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL || '';
  const key =
    opts?.key ||
    process.env.SUPABASE_SERVICE_ROLE_KEY ||
    process.env.SUPABASE_ANON_KEY ||
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
    '';
  return { url, key };
}

function makeSupabase(opts?: { url?: string; key?: string }): SupabaseClient {
  const { url, key } = resolveEnv(opts);
  if (!url || !key) {
    throw new Error(
      '[db] Supabase 未設定：需要 SUPABASE_URL（或 NEXT_PUBLIC_SUPABASE_URL）與 SUPABASE_SERVICE_ROLE_KEY（或 SUPABASE_ANON_KEY）。',
    );
  }
  return createClient(url, key, { auth: { persistSession: false } });
}

// ── where / orderBy 轉換 ──────────────────────────────────────
type AnyObj = Record<string, any>;

function applyWhere(q: any, where?: AnyObj): any {
  if (!where) return q;
  for (const [key, value] of Object.entries(where)) {
    if (value === undefined) continue;
    if (key === 'AND' && Array.isArray(value)) {
      for (const sub of value) q = applyWhere(q, sub);
      continue;
    }
    if (key === 'OR' && Array.isArray(value)) {
      const parts: string[] = [];
      for (const sub of value) {
        const collected: string[] = [];
        collectFilters(sub, collected);
        parts.push(collected.length === 1 ? collected[0] : `and(${collected.join(',')})`);
      }
      if (parts.length) q = q.or(parts.join(','));
      continue;
    }
    if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
      const cond = value as AnyObj;
      if ('in' in cond) q = q.in(key, cond.in as any[]);
      if ('gt' in cond) q = q.gt(key, cond.gt as any);
      if ('lt' in cond) q = q.lt(key, cond.lt as any);
      if ('gte' in cond) q = q.gte(key, cond.gte as any);
      if ('lte' in cond) q = q.lte(key, cond.lte as any);
      if ('contains' in cond) q = q.ilike(key, `%${String(cond.contains)}%`);
      if ('not' in cond && cond.not !== undefined && typeof cond.not !== 'object') q = q.neq(key, cond.not);
      continue;
    }
    q = q.eq(key, value);
  }
  return q;
}

function collectFilters(where: AnyObj, out: string[]): void {
  for (const [key, value] of Object.entries(where)) {
    if (value === undefined) continue;
    if (key === 'AND' && Array.isArray(value)) {
      const parts: string[] = [];
      for (const sub of value) collectFilters(sub, parts);
      out.push(`and(${parts.join(',')})`);
      continue;
    }
    if (key === 'OR' && Array.isArray(value)) {
      const parts: string[] = [];
      for (const sub of value) collectFilters(sub, parts);
      out.push(`or(${parts.join(',')})`);
      continue;
    }
    if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
      const cond = value as AnyObj;
      if ('in' in cond) out.push(`${key}.in.(${(cond.in as any[]).map((v) => String(v)).join(',')})`);
      if ('gt' in cond) out.push(`${key}.gt.${cond.gt}`);
      if ('lt' in cond) out.push(`${key}.lt.${cond.lt}`);
      if ('gte' in cond) out.push(`${key}.gte.${cond.gte}`);
      if ('lte' in cond) out.push(`${key}.lte.${cond.lte}`);
      if ('contains' in cond) out.push(`${key}.ilike.*${String(cond.contains)}*`);
      continue;
    }
    const v = typeof value === 'string' ? `"${value.replace(/"/g, '\\"')}"` : String(value);
    out.push(`${key}.eq.${v}`);
  }
}

function applyOrderBy(q: any, orderBy?: AnyObj | AnyObj[]): any {
  if (!orderBy) return q;
  const entries = Array.isArray(orderBy) ? orderBy : [orderBy];
  for (const entry of entries) {
    for (const [field, dir] of Object.entries(entry)) {
      q = q.order(field, { ascending: dir !== 'desc' });
    }
  }
  return q;
}

// ── include 解析 ──────────────────────────────────────────────
async function attachIncludes(
  supa: SupabaseClient,
  modelKey: string,
  rows: AnyObj[],
  include?: AnyObj,
): Promise<void> {
  if (!include || rows.length === 0) return;

  // _count: { select: { <rel>: true } }
  if (include._count?.select) {
    const rels0 = RELATIONS[modelKey] || {};
    for (const [relKey, specRaw] of Object.entries(include._count.select)) {
      if (!specRaw) continue;
      const spec = (rels0[relKey] || {}) as { table: string; type: 'many' | 'one'; fk: string };
      if (!spec.table) continue;
      const relTable = tableFor(spec.table);
      const ids = rows.map((r) => r.id).filter(Boolean) as any[];
      if (ids.length === 0) {
        for (const r of rows) {
          if (!r._count) r._count = {};
          r._count[relKey] = 0;
        }
        continue;
      }
      const { data, error } = await supa.from(relTable).select(spec.fk).in(spec.fk, ids);
      const counts = new Map<string, number>();
      if (!error && data) {
        for (const row of data as AnyObj[]) {
          const k = String(row[spec.fk]);
          counts.set(k, (counts.get(k) || 0) + 1);
        }
      }
      for (const r of rows) {
        if (!r._count) r._count = {};
        r._count[relKey] = counts.get(String(r.id)) || 0;
      }
    }
  }

  const rels = RELATIONS[modelKey] || {};
  for (const [relKey, specRaw] of Object.entries(rels)) {
    const includeVal = include[relKey];
    if (!includeVal) continue;
    const spec = specRaw as { table: string; type: 'many' | 'one'; fk: string };
    const relTable = tableFor(spec.table);
    const subInclude =
      typeof includeVal === 'object' && includeVal !== null && !Array.isArray(includeVal)
        ? (includeVal as AnyObj).include
        : undefined;
    const subWhere =
      typeof includeVal === 'object' && includeVal !== null && !Array.isArray(includeVal)
        ? (includeVal as AnyObj).where
        : undefined;

    if (spec.type === 'many') {
      const ids = rows.map((r) => r.id).filter(Boolean);
      if (ids.length === 0) continue;
      let q = supa.from(relTable).select('*').in(spec.fk, ids as any[]);
      q = applyWhere(q, subWhere);
      const { data, error } = await q;
      if (error || !data) {
        for (const r of rows) r[relKey] = [];
        continue;
      }
      await attachIncludes(supa, spec.table, data as AnyObj[], subInclude);
      const byParent = new Map<string, AnyObj[]>();
      for (const child of data as AnyObj[]) {
        const pk = String(child[spec.fk]);
        if (!byParent.has(pk)) byParent.set(pk, []);
        byParent.get(pk)!.push(child);
      }
      for (const r of rows) r[relKey] = byParent.get(String(r.id)) || [];
    } else {
      const fks = [...new Set(rows.map((r) => r[spec.fk]).filter((v) => v !== null && v !== undefined))] as any[];
      if (fks.length === 0) {
        for (const r of rows) r[relKey] = null;
        continue;
      }
      let q = supa.from(relTable).select('*').in('id', fks);
      const { data, error } = await q;
      if (error || !data) {
        for (const r of rows) r[relKey] = null;
        continue;
      }
      await attachIncludes(supa, spec.table, data as AnyObj[], subInclude);
      const byId = new Map<string, AnyObj>();
      for (const row of data as AnyObj[]) byId.set(String(row.id), row);
      for (const r of rows) r[relKey] = r[spec.fk] ? byId.get(String(r[spec.fk])) || null : null;
    }
  }
}

function unwrap(result: { data: any; error: any }, what: string): any {
  if (result.error) {
    throw new Error(`[db] ${what} 失敗: ${result.error.message}`);
  }
  return result.data;
}

// ── Model delegate ────────────────────────────────────────────
// getSupa 為延遲取得 SupabaseClient 的 getter：建構 delegate 不觸發連線，
// 首次實際查詢才解析環境變數並建立客戶端。
class ModelDelegate {
  constructor(private getSupa: () => SupabaseClient, private modelKey: string) {}

  private get table() { return tableFor(this.modelKey); }
  private from() { return this.getSupa().from(this.table); }

  private flattenWhere(where: AnyObj): AnyObj {
    // 支援複合唯一鍵（如 userId_taskId: { userId, taskId }）
    const flat: AnyObj = {};
    for (const [key, value] of Object.entries(where || {})) {
      if (
        value !== null &&
        typeof value === 'object' &&
        !Array.isArray(value) &&
        (value as AnyObj).in === undefined &&
        (value as AnyObj).gt === undefined &&
        (value as AnyObj).lt === undefined &&
        (value as AnyObj).gte === undefined &&
        (value as AnyObj).lte === undefined &&
        (value as AnyObj).contains === undefined
      ) {
        const o = value as AnyObj;
        if (Object.keys(o).length > 0 && Object.values(o).every((v) => typeof v !== 'object')) {
          Object.assign(flat, o);
          continue;
        }
      }
      flat[key] = value;
    }
    return flat;
  }

  async findUnique(args: { where: AnyObj; select?: AnyObj; include?: AnyObj }): Promise<any> {
    const flat = this.flattenWhere(args.where);
    const cols = args.select ? Object.keys(args.select).join(',') : '*';
    let q = this.from().select(cols);
    q = applyWhere(q, flat);
    const data = unwrap(await q.maybeSingle(), `${this.modelKey}.findUnique`);
    if (data && args.include && !args.select) await attachIncludes(this.getSupa(), this.modelKey, [data], args.include);
    return data;
  }

  async findFirst(args: AnyObj = {}): Promise<any> {
    const flat = args.where ? this.flattenWhere(args.where) : undefined;
    const cols = args.select ? Object.keys(args.select).join(',') : '*';
    let q = this.from().select(cols);
    q = applyWhere(q, flat);
    q = applyOrderBy(q, args.orderBy);
    const data = unwrap(await q.limit(1).maybeSingle(), `${this.modelKey}.findFirst`);
    if (data && args.include && !args.select) await attachIncludes(this.getSupa(), this.modelKey, [data], args.include);
    return data;
  }

  async findMany(args: AnyObj = {}): Promise<any[]> {
    const flat = args.where ? this.flattenWhere(args.where) : undefined;
    const cols = args.select ? Object.keys(args.select).join(',') : '*';
    let q = this.from().select(cols);
    q = applyWhere(q, flat);
    q = applyOrderBy(q, args.orderBy);
    if (typeof args.take === 'number') q = q.limit(args.take);
    if (typeof args.skip === 'number' && args.skip > 0) q = q.range(args.skip, args.skip + (args.take ?? 1000) - 1);
    const data = unwrap(await q, `${this.modelKey}.findMany`) as AnyObj[];
    if (args.include && !args.select) await attachIncludes(this.getSupa(), this.modelKey, data, args.include);
    return data;
  }

  async create(args: { data: AnyObj }): Promise<any> {
    const data: AnyObj = { ...args.data };
    // 巢狀寫入：data.<relKey>.create = [ ... ]（子表 fk = 本表 id）
    const rels = RELATIONS[this.modelKey] || {};
    const pendingChildren: Array<{ table: string; fk: string; rows: AnyObj[] }> = [];
    for (const [relKey, specRaw] of Object.entries(rels)) {
      const nested = data[relKey];
      if (nested && typeof nested === 'object' && Array.isArray((nested as AnyObj).create)) {
        const spec = specRaw as { table: string; type: string; fk: string };
        if (spec.type === 'many') {
          pendingChildren.push({ table: tableFor(spec.table), fk: spec.fk, rows: (nested as AnyObj).create as AnyObj[] });
          delete data[relKey];
        }
      }
    }
    const row = unwrap(await this.from().insert(data).select().single(), `${this.modelKey}.create`);
    for (const child of pendingChildren) {
      const payload = child.rows.map((r) => ({ ...r, [child.fk]: row.id }));
      await this.getSupa().from(child.table).insert(payload);
    }
    return row;
  }

  async createMany(args: { data: AnyObj[] }): Promise<{ count: number }> {
    const data = unwrap(await this.from().insert(args.data), `${this.modelKey}.createMany`);
    return { count: Array.isArray(data) ? data.length : args.data.length };
  }

  async update(args: { where: AnyObj; data: AnyObj }): Promise<any> {
    const flat = this.flattenWhere(args.where);
    return unwrap(await this.from().update(args.data).match(flat).select().single(), `${this.modelKey}.update`);
  }

  async updateMany(args: { where: AnyObj; data: AnyObj }): Promise<{ count: number }> {
    let q = this.from().update(args.data);
    q = applyWhere(q, this.flattenWhere(args.where));
    const data = unwrap(await q.select(), `${this.modelKey}.updateMany`);
    return { count: Array.isArray(data) ? data.length : 0 };
  }

  async upsert(args: { where: AnyObj; update?: AnyObj; create: AnyObj }): Promise<any> {
    const flat = this.flattenWhere(args.where);
    const existing = unwrap(
      await applyWhere(this.from().select('id'), flat).limit(1).maybeSingle(),
      `${this.modelKey}.upsert.lookup`,
    );
    if (existing) {
      const merged = { ...(args.update || {}), id: existing.id };
      return unwrap(await this.from().update(merged).eq('id', existing.id).select().single(), `${this.modelKey}.upsert.update`);
    }
    return unwrap(await this.from().insert(args.create).select().single(), `${this.modelKey}.upsert.create`);
  }

  async delete(args: { where: AnyObj }): Promise<any> {
    const flat = this.flattenWhere(args.where);
    return unwrap(await this.from().delete().match(flat).select().single(), `${this.modelKey}.delete`);
  }

  async deleteMany(args: { where: AnyObj }): Promise<{ count: number }> {
    let q = this.from().delete();
    q = applyWhere(q, this.flattenWhere(args.where));
    const data = unwrap(await q.select(), `${this.modelKey}.deleteMany`);
    return { count: Array.isArray(data) ? data.length : 0 };
  }

  async count(args: AnyObj = {}): Promise<number> {
    let q = this.from().select('id', { count: 'exact', head: true });
    q = applyWhere(q, args.where ? this.flattenWhere(args.where) : undefined);
    const res = await q;
    if (res.error) throw new Error(`[db] ${this.modelKey}.count 失敗: ${res.error.message}`);
    return res.count ?? 0;
  }
}

// ── Raw SQL（Node 環境下經 pg 連線池；Worker 環境不支援）────
let _pool: any = null;
async function getPool(): Promise<any> {
  if (_pool) return _pool;
  const { Pool } = await import('pg');
  _pool = new Pool({
    connectionString:
      process.env.DATABASE_URL ||
      process.env.PGVECTOR_URL ||
      process.env.SUPABASE_DB_URL ||
      '',
    max: 10,
    idleTimeoutMillis: 30000,
    connectionTimeoutMillis: 5000,
  });
  return _pool;
}

function rawText(segments: TemplateStringsArray, values: any[]): string {
  return segments.reduce((acc, seg, i) => acc + seg + (i < values.length ? '$' + (i + 1) : ''), '');
}

async function rawQuery(segments: TemplateStringsArray, values: any[]): Promise<any[]> {
  const pool = await getPool();
  const result = await pool.query(rawText(segments, values), values);
  return result.rows as any[];
}

async function rawExecute(segments: TemplateStringsArray, values: any[]): Promise<number> {
  const pool = await getPool();
  const result = await pool.query(rawText(segments, values), values);
  return result.rowCount || 0;
}

// ── Compat client ────────────────────────────────────────────
export class PrismaCompatClient {
  private _opts?: { url?: string; key?: string };
  private _supa: SupabaseClient | null = null;
  readonly [key: string]: any;

  constructor(opts?: { url?: string; key?: string }) {
    // 延遲建構：建構子不解析環境變數、不建立連線（見檔頭說明）。
    this._opts = opts;
    return new Proxy(this, {
      get(target, prop) {
        if (prop in target || typeof prop === 'symbol') return (target as any)[prop];
        return new ModelDelegate(() => target.supa(), String(prop));
      },
    }) as PrismaCompatClient;
  }

  /** 首次實際查詢才建立 SupabaseClient；缺少設定時於此處拋錯。 */
  private supa(): SupabaseClient {
    if (!this._supa) this._supa = makeSupabase(this._opts);
    return this._supa;
  }

  async $connect(): Promise<void> { /* supabase-js 為無狀態 HTTP，無需連線 */ }
  async $disconnect(): Promise<void> { /* no-op */ }

  async $queryRaw<T = any[]>(strings: TemplateStringsArray, ...values: any[]): Promise<T> {
    return rawQuery(strings, values) as Promise<T>;
  }

  async $executeRaw<T = number>(strings: TemplateStringsArray, ...values: any[]): Promise<T> {
    return rawExecute(strings, values) as unknown as Promise<T>;
  }

  async $transaction(fnOrOps: any, ...rest: any[]): Promise<any> {
    if (typeof fnOrOps === 'function') return fnOrOps(this);
    // 陣列型操作：循序執行（不保證原子性；如需嚴格交易請用 $queryRaw + BEGIN/COMMIT）
    const results: any[] = [];
    for (const op of [fnOrOps, ...rest]) {
      if (op && typeof op.then === 'function') results.push(await op);
    }
    return results;
  }
}

export type PrismaClient = PrismaCompatClient;

export function createPrismaCompatClient(opts?: { url?: string; key?: string }): PrismaClient {
  return new PrismaCompatClient(opts);
}

// [agent:9][squad:符文契約][lifecycle:active][p2][platform:esggo][best-practice:結界]
/**
 * Firebase 相容層 (Supabase Adapter) — GCP Firebase 已停用，改由 Supabase 接手。
 * 
 * 此檔案透過封裝 Supabase JS Client 來模擬 Firebase Firestore 的 API，
 * 讓既有的 23+ 個依賴 Firebase 語法的元件不需大幅重構即可無縫切換到 Supabase Postgres。
 */

import { supabase } from './supabase-client';
import { syncEngine } from './supabase-sync-engine';

type DocData = Record<string, unknown>;

class QueryBuilder {
  constructor(
    public collection: string,
    public wheres: Array<{ field: string; op: string; value: unknown }> = [],
    public order: { field: string; dir: 'asc' | 'desc' } | null = null,
    public lim: number | null = null
  ) {}

  where(field: string, op: string, value: unknown): QueryBuilder {
    return new QueryBuilder(this.collection, [...this.wheres, { field, op, value }], this.order, this.lim);
  }
  orderBy(field: string, dir: 'asc' | 'desc' = 'desc'): QueryBuilder {
    return new QueryBuilder(this.collection, this.wheres, { field, dir }, this.lim);
  }
  limit(n: number): QueryBuilder {
    return new QueryBuilder(this.collection, this.wheres, this.order, n);
  }

  async get(): Promise<QuerySnapshot> {
    let q = supabase.from(this.collection).select('*');
    for (const w of this.wheres) {
      if (w.op === '==') q = q.eq(w.field, w.value);
      if (w.op === '!=') q = q.neq(w.field, w.value);
      if (w.op === '>') q = q.gt(w.field, w.value);
      if (w.op === '>=') q = q.gte(w.field, w.value);
      if (w.op === '<') q = q.lt(w.field, w.value);
      if (w.op === '<=') q = q.lte(w.field, w.value);
    }
    if (this.order) {
      q = q.order(this.order.field, { ascending: this.order.dir === 'asc' });
    }
    if (this.lim !== null) {
      q = q.limit(this.lim);
    }

    const { data, error } = await q;
    if (error) {
      console.error(`Supabase query error on ${this.collection}:`, error);
      return new QuerySnapshot([]);
    }

    return new QuerySnapshot((data || []).map((row: any) => ({
      id: row.id,
      data: () => row
    })));
  }
}

class QuerySnapshot {
  constructor(public docs: Array<{ id: string; data: () => DocData }>) {}
  get size(): number { return this.docs.length; }
  get empty(): boolean { return this.docs.length === 0; }
  forEach(cb: (doc: { id: string; data: () => DocData }) => void): void {
    this.docs.forEach(cb);
  }
}

class DocRef {
  constructor(public collection: string, public id: string) {}

  async get(): Promise<{ exists: boolean; id: string; data: () => DocData | null }> {
    const { data, error } = await supabase.from(this.collection).select('*').eq('id', this.id).single();
    if (error || !data) return { exists: false, id: this.id, data: () => null };
    return { exists: true, id: this.id, data: () => data };
  }
  async set(data: DocData, opts?: { merge?: boolean }): Promise<void> {
    if (opts?.merge) {
      syncEngine.pushTask(this.collection, 'UPDATE', { id: this.id, ...data });
    } else {
      syncEngine.pushTask(this.collection, 'UPDATE', { id: this.id, ...data }); // Upsert can be mapped to UPDATE in our sync engine since offline fallback will handle it
    }
  }
  async delete(): Promise<void> {
    syncEngine.pushTask(this.collection, 'DELETE', { id: this.id });
  }
}

class CollectionRef {
  constructor(public name: string) {}
  doc(id: string): DocRef { return new DocRef(this.name, id); }

  async add(data: DocData): Promise<{ id: string }> {
    const id = `${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
    syncEngine.pushTask(this.name, 'INSERT', { id, ...data });
    return { id };
  }
  where(field: string, op: string, value: unknown): QueryBuilder { return new QueryBuilder(this.name).where(field, op, value); }
  orderBy(field: string, dir: 'asc' | 'desc' = 'desc'): QueryBuilder { return new QueryBuilder(this.name).orderBy(field, dir); }
  limit(n: number): QueryBuilder { return new QueryBuilder(this.name).limit(n); }
  async get(): Promise<QuerySnapshot> { return new QueryBuilder(this.name).get(); }
}

export const db = { __local: false, __supabase: true as const };

export function collection(_db: unknown, name: string): CollectionRef { return new CollectionRef(name); }
export function doc(_db: unknown, collectionName: string, id: string): DocRef { return new DocRef(collectionName, id); }

export function query(ref: QueryBuilder | CollectionRef, ...constraints: Array<(r: QueryBuilder) => QueryBuilder>): QueryBuilder {
  const builder = ref instanceof CollectionRef ? new QueryBuilder(ref.name) : ref;
  return constraints.reduce((acc, c) => c(acc), builder);
}

export function where(field: string, op: string, value: unknown): (r: QueryBuilder) => QueryBuilder {
  return (r: QueryBuilder) => r.where(field, op, value);
}
export function orderBy(field: string, dir: 'asc' | 'desc' = 'desc'): (r: QueryBuilder) => QueryBuilder {
  return (r: QueryBuilder) => r.orderBy(field, dir);
}
export function limit(n: number): (r: QueryBuilder) => QueryBuilder {
  return (r: QueryBuilder) => r.limit(n);
}

export async function getDocs(q: QueryBuilder | CollectionRef): Promise<QuerySnapshot> {
  const builder = q instanceof CollectionRef ? new QueryBuilder(q.name) : q;
  return builder.get();
}
export async function getDoc(ref: DocRef): Promise<{ exists: boolean; id: string; data: () => DocData | null }> {
  return ref.get();
}
export async function addDoc(ref: CollectionRef, data: DocData): Promise<{ id: string }> {
  return ref.add(data);
}
export async function setDoc(ref: DocRef, data: DocData): Promise<void> {
  return ref.set(data);
}
export async function updateDoc(ref: DocRef, data: DocData): Promise<void> {
  return ref.set(data, { merge: true });
}
export async function deleteDoc(ref: DocRef): Promise<void> {
  return ref.delete();
}

/**
 * onSnapshot — 將 Firestore 的即時監聽映射到 Supabase Realtime Channel
 */
export function onSnapshot(
  ref: QueryBuilder | CollectionRef,
  callback: (snapshot: QuerySnapshot) => void,
  onError?: (error: Error) => void
): () => void {
  const collectionName = ref instanceof CollectionRef ? ref.name : ref.collection;
  const builder = ref instanceof CollectionRef ? new QueryBuilder(ref.name) : ref;

  // 初始載入
  builder.get().then(callback).catch(e => onError?.(e));

  // 監聽變更
  const channel = supabase
    .channel(`public:${collectionName}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: collectionName }, () => {
      builder.get().then(callback).catch(e => onError?.(e));
    })
    .subscribe();

  return () => {
    supabase.removeChannel(channel);
  };
}

export function writeBatch(_db: unknown): {
  set: (ref: DocRef, data: DocData) => void;
  delete: (ref: DocRef) => void;
  commit: () => Promise<void>;
} {
  const ops: Array<() => Promise<void>> = [];
  return {
    set: (ref, data) => { ops.push(async () => { await ref.set(data); }); },
    delete: (ref) => { ops.push(async () => { await ref.delete(); }); },
    commit: async () => {
      for (const op of ops) await op();
    },
  };
}

import ollama from 'ollama';

export class GoogleGenAI {
  constructor(options: any) {}

  [key: string]: any; // Allow arbitrary extensions like interactions

  models = {
    generateContent: async ({ model, contents }: any) => {
      let text = '';
      if (typeof contents === 'string') {
        text = contents;
      } else if (Array.isArray(contents)) {
        text = contents.map(c => typeof c === 'string' ? c : (c.text || JSON.stringify(c))).join('\n');
      } else {
        text = JSON.stringify(contents);
      }

      try {
        const response = await ollama.generate({
          model: 'qwen2.5:14b', // Using Ollama default for esggo local inference
          prompt: text
        });
        return { text: response.response };
      } catch (e) {
        console.error('Ollama generateContent failed:', e);
        return { text: 'Ollama local inference failed' };
      }
    },
    embedContent: async ({ model, contents }: any) => {
      try {
        const text = Array.isArray(contents) ? contents.join('\n') : String(contents);
        const response = await ollama.embeddings({
          model: 'nomic-embed-text', // Or another embedding model you have pulled
          prompt: text
        });
        return { embeddings: [{ values: response.embedding }] };
      } catch (e) {
        console.error('Ollama embedContent failed:', e);
        return { embeddings: [{ values: new Array(768).fill(0) }] };
      }
    }
  };

  // Interactions API support (used by village/trends route when USE_INTERACTIONS_API=true)
  // Default implementation throws — override with real Gemini Interactions API when needed.
  interactions = {
    create: async (_params: any): Promise<{ steps?: Array<{ type?: string; content?: Array<{ parts?: Array<{ text?: string }> }> }> }> => {
      throw new Error('Interactions API not implemented. Use models.generateContent instead.');
    }
  };
}

