  if (useFirebase && db) {
    await deleteDoc(doc(db, 'platforms', APP_ID, 'submissions', id));
  } else if (useNcb) {
    await ncbSubmissions.delete(id, APP_ID);
  } else {
    const all = loadLocal().filter((item) => item.id !== id);
    saveLocal(all);
    notifyLocal();
  }

  emitTelemetry('submission_deleted', { id });
};

